import React from 'react';

export const SSB_LOGO_DATA_URI = "data:image/svg+xml;base64,";

interface SSBCrestLogoProps extends React.ImgHTMLAttributes<HTMLImageElement> {
  className?: string;
}

export const SSBCrestLogo: React.FC<SSBCrestLogoProps> = ({ className, alt = 'Sashastra Seema Bal', ...props }) => {
  return (
    <img
      src={SSB_LOGO_DATA_URI}
      alt={alt}
      className={className}
      draggable={false}
      {...props}
    />
  );
};
